import java.util.*;

class LRUCache {
    private final int capacity;
    private final Map<Integer, Node> map;
    private final Node head; // dummy head
    private final Node tail; // dummy tail

    public LRUCache(int capacity) {
        if (capacity <= 0) throw new IllegalArgumentException("capacity must be > 0");
        this.capacity = capacity;
        this.map = new HashMap<>(capacity); // 预分配减少扩容
        this.head = new Node(0, 0);
        this.tail = new Node(0, 0);
        head.next = tail;
        tail.prev = head;
    }

    public int get(int key) {
        Node node = map.get(key);       // O(1) 定位
        if (node == null) return -1;
        moveToHead(node);               // 命中，标记为最近使用
        return node.value;
    }

    public void put(int key, int value) {
        Node node = map.get(key);
        if (node != null) {
            // key 已存在：更新值 + 移到头部
            node.value = value;
            moveToHead(node);
        } else {
            // key 不存在
            if (map.size() == capacity) {
                // 容量满：淘汰最久未访问的节点 (tail.prev)
                Node lru = tail.prev;
                removeNode(lru);        // 从链表摘除
                map.remove(lru.key);    // 同步删除 map 映射
            }
            Node newNode = new Node(key, value);
            map.put(key, newNode);
            addToHead(newNode);
        }
    }

    // 从链表中摘除节点（O(1)，不涉及 map）
    private void removeNode(Node node) {
        node.prev.next = node.next;
        node.next.prev = node.prev;
    }

    // 插入到 head 之后（即链表头部）
    private void addToHead(Node node) {
        node.next = head.next;
        node.prev = head;
        head.next.prev = node;
        head.next = node;
    }

    // 摘除 + 插入头部 = 移到最前面
    private void moveToHead(Node node) {
        removeNode(node);
        addToHead(node);
    }

    private static class Node {
        final int key;  // key 必须存，因为淘汰时要从 map 里 remove
        int value;
        Node prev, next;
        Node(int key, int value) {
            this.key = key;
            this.value = value;
        }
    }

    // 测试
    public static void main(String[] args) {
        LRUCache cache = new LRUCache(2);
        cache.put(1, 1);
        cache.put(2, 2);
        System.out.println(cache.get(1)); // 1
        cache.put(3, 3);                  // 淘汰 key=2
        System.out.println(cache.get(2)); // -1
        cache.put(4, 4);                  // 淘汰 key=1
        System.out.println(cache.get(1)); // -1
        System.out.println(cache.get(3)); // 3
        System.out.println(cache.get(4)); // 4
    }
}
